# Root system architecture responds to the nutrient supply (schematic of a dicot seedling root system,
# generated by a simple branching rule). A: uniform, moderate supply. B: a local patch rich in nitrate (shaded):
# lateral roots that grow into the patch elongate and branch much more, while laterals elsewhere stay short
# (the response first described for barley by Drew in 1975; phosphate and ammonium patches act similarly).
# C: phosphate deficiency: the primary root slows, laterals and root hairs multiply near the surface where
# phosphate (immobile, bound in the topsoil) is concentrated, a "topsoil foraging" architecture.
# D: abundant, uniform nitrogen: a smaller root system relative to the shoot (lower root-to-shoot ratio).
import numpy as np

import wikibio as bio

P = bio.P
fig, ax = bio.canvas(28.0, 12.0)
ink = P.edge("cell_wall")


def lateral(x, y, side, L, angle_deg, rich=None, order=1):
    a = np.radians(angle_deg)
    n = 12
    pts = [(x, y)]
    for k in range(1, n + 1):
        t = k / n
        ang = a + side * 0.0 - 0.35 * t  # gravitropic bending downwards
        px = x + side * L * t * np.cos(abs(ang))
        py = y - L * t * np.sin(abs(ang)) - 0.15 * L * t * t
        pts.append((px, py))
    pts = np.array(pts)
    ax.plot(pts[:, 0], pts[:, 1], color=ink, lw=1.6 / order, solid_capstyle="round", zorder=6)
    if order == 1:
        nb = 3 if rich is None else 0
        for j in range(1, nb + 1):
            p = pts[int(j * n / (nb + 1))]
            lateral(p[0], p[1], side, L * 0.25, angle_deg + 25, order=2)
    return pts


def system(x0, top, depth, laterals, length_fn, title, letter, patch=None, shoot=1.0, hairs=False):
    bio.panel(ax, letter, (x0 - 3.3, 11.8))
    bio.label(ax, (x0 - 2.6, 11.75), title, size="small", bold=True, ha="left", va="top")
    if patch is not None:
        (px0, py0, pw, ph) = patch
        ax.add_patch(__import__("matplotlib").patches.FancyBboxPatch((px0, py0), pw, ph, boxstyle="round,pad=0,rounding_size=0.3",
                     facecolor=P.fill("dna2"), edgecolor=P.edge("dna2"), lw=0.9, alpha=0.6, zorder=2))
        bio.label(ax, (px0 + pw / 2, py0 + ph + 0.3), "nitrate-rich patch", size="tiny", color=P.edge("dna"))
    # shoot
    ax.plot([x0, x0], [top, top + 1.6 * shoot], color=P.edge("plant"), lw=2.2, zorder=5)
    for s in (-1, 1):
        ax.add_patch(__import__("matplotlib").patches.Ellipse((x0 + s * 0.55 * shoot, top + 1.35 * shoot), 1.0 * shoot,
                     0.45 * shoot, angle=s * 25, facecolor=P.fill("plant"), edgecolor=P.edge("plant"), lw=1, zorder=5))
    ax.plot([x0 - 3.2, x0 + 3.2], [top, top], color=P.muted(), lw=0.8)
    ax.plot([x0, x0], [top, top - depth], color=ink, lw=2.4, solid_capstyle="round", zorder=6)
    for k in range(laterals):
        y = top - 0.4 - (depth - 0.8) * k / max(laterals - 1, 1)
        side = 1 if k % 2 == 0 else -1
        L, rich = length_fn(y, side)
        pts = lateral(x0, y, side, L, 20, rich=None if not rich else True)
        if rich:
            for j in range(2, 12, 2):
                p = pts[j]
                for s2 in (-1, 1):
                    lateral(p[0], p[1], s2, 0.7, 40, order=2)
        if hairs and y > top - 2.0:
            for p in pts[1::2]:
                ax.plot([p[0], p[0] + 0.12], [p[1], p[1] - 0.18], color=ink, lw=0.5, zorder=6)


top = 9.0
system(3.6, top, 7.0, 10, lambda y, s: (1.5, False), "Uniform supply", "A")
patch = (9.85, 3.9, 3.0, 2.9)


def patch_len(y, s):
    inside = s > 0 and 4.6 < y < 6.6
    return (2.4 if inside else 1.0), inside


system(10.6 - 0.9, top, 7.0, 12, patch_len, "Local nitrate patch", "B", patch=patch)
system(17.0, top, 3.6, 14, lambda y, s: (2.2 - 0.25 * (top - y), False), "Low phosphate", "C", hairs=True)
system(23.8, top, 4.2, 7, lambda y, s: (1.0, False), "Abundant nitrogen", "D", shoot=1.3)
bio.label(ax, (23.8, 3.8), "small root system,\nlow root-to-shoot ratio", size="tiny", color=P.muted())
bio.label(ax, (17.0, 4.6), "shallow, many laterals\nand root hairs", size="tiny", color=P.muted())
